from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum


class CheckKind(Enum):
    """The kinds of checks performed against a package change."""

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """The outcome of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


@dataclass
class CheckResult:
    """The result of running a single check."""

    status: CheckStatus
    details: str


@dataclass
class PackageChange:
    """A single package version change detected in a diff."""

    name: str
    old_version: str | None
    new_version: str
    checks: dict[CheckKind, CheckResult] = field(default_factory=dict)
    repo_url: str | None = None

    @property
    def needs_agent(self) -> bool:
        """Return True if at least one check needs agent attention."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT
            for result in self.checks.values()
        )


@dataclass
class CheckRunResult:
    """The result of running all checks for a pull request."""

    pr_number: int
    packages: list[PackageChange] = field(default_factory=list)

    @property
    def needs_agent(self) -> bool:
        """Return True if any package needs agent attention."""
        return any(package.needs_agent for package in self.packages)

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation of the run."""
        # Imported lazily to avoid a circular import (render imports models).
        from .render import render_comment

        checks = []
        for package in self.packages:
            checks.append(
                {
                    "name": package.name,
                    "old_version": package.old_version,
                    "new_version": package.new_version,
                    "repo_url": package.repo_url,
                    "needs_agent": package.needs_agent,
                    "checks": {
                        kind.value: {
                            "status": result.status.value,
                            "details": result.details,
                        }
                        for kind, result in package.checks.items()
                    },
                }
            )

        data: dict = {
            "pr_number": self.pr_number,
            "rendered_comment": render_comment(self),
            "needs_agent": self.needs_agent,
            "packages": [
                {
                    "name": package.name,
                    "old_version": package.old_version,
                    "new_version": package.new_version,
                    "repo_url": package.repo_url,
                    "needs_agent": package.needs_agent,
                }
                for package in self.packages
            ],
            "checks": checks,
        }

        # Per-kind aggregate: does any package need agent attention for it?
        for kind in CheckKind:
            data[kind.value] = any(
                (result := package.checks.get(kind)) is not None
                and result.status is CheckStatus.NEEDS_AGENT
                for package in self.packages
            )

        return data
