from __future__ import annotations

from fnmatch import fnmatch
import re

from .models import PackageChange

# Requirement line: an optional extras group, pinned with ``==``.
_REQ_RE = re.compile(
    r"^([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*==\s*([^\s;#]+)"
)


def _canonical_name(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _target_path(header: str) -> str:
    """Extract the file path from a ``+++`` diff header."""
    path = header[4:].split("\t", 1)[0].strip()
    if path.startswith(("a/", "b/")):
        path = path[2:]
    return path


def _is_tracked(path: str) -> bool:
    """Return True if the path is a tracked ``requirements*.txt`` file."""
    basename = path.rsplit("/", 1)[-1]
    return fnmatch(basename, "requirements*.txt")


def _record(content: str, store: dict[str, str]) -> None:
    """Parse a requirement line and record its canonical name/version."""
    # Strip inline comments and surrounding whitespace before parsing.
    stripped = content.split("#", 1)[0].strip()
    if not stripped:
        return
    match = _REQ_RE.match(stripped)
    if match is None:
        return
    store[_canonical_name(match.group(1))] = match.group(2)


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff string into a list of ``PackageChange`` objects."""
    tracked = False
    added: dict[str, str] = {}
    removed: dict[str, str] = {}

    for line in diff_text.splitlines():
        if line.startswith("diff --git"):
            tracked = False
            continue
        if line.startswith("+++ "):
            tracked = _is_tracked(_target_path(line))
            continue
        if line.startswith("--- ") or line.startswith("@@"):
            continue
        if not tracked:
            continue
        if line.startswith("+"):
            _record(line[1:], added)
        elif line.startswith("-"):
            _record(line[1:], removed)

    changes: list[PackageChange] = []
    for name, new_version in added.items():
        old_version = removed.get(name)
        if old_version == new_version:
            # No version change; ignore.
            continue
        changes.append(
            PackageChange(
                name=name,
                old_version=old_version,
                new_version=new_version,
            )
        )

    return changes
