from __future__ import annotations

from dataclasses import dataclass
from urllib.parse import urlparse

import requests

PYPI_BASE = "https://pypi.org"
_TIMEOUT = 30

# Hostnames considered known code hosts (exact match only).
_KNOWN_CODE_HOSTS = frozenset(
    {"github.com", "gitlab.com", "www.github.com", "www.gitlab.com"}
)


@dataclass
class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    project_urls: dict
    repo_url: str | None
    file_provenance_urls: list[str]
    found: bool


@dataclass
class ProvenanceResult:
    """Result of a provenance/attestation check."""

    has_attestation: bool
    publisher_kind: str | None
    recognized_publisher: bool
    detail: str


def _sanitize(value: str) -> str:
    """Strip backtick and newline characters from a value."""
    return value.replace("`", "").replace("\n", "").replace("\r", "")


def _get_json(url: str) -> tuple[object | None, int | None]:
    """Fetch and decode JSON, returning ``(data, status_code)``.

    ``data`` is ``None`` on any failure (network error, >=400 status, or
    invalid JSON). ``status_code`` is ``None`` only on network errors.
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return None, None
    status = response.status_code
    if status == 404:
        return None, 404
    if status >= 400:
        return None, status
    try:
        return response.json(), status
    except ValueError:
        return None, status


def _extract_project_urls(data: object) -> dict:
    """Pull the ``project_urls`` mapping out of a PyPI JSON payload."""
    if not isinstance(data, dict):
        return {}
    info = data.get("info") or {}
    urls = info.get("project_urls") or {}
    return urls if isinstance(urls, dict) else {}


def _is_known_code_host(url: str) -> bool:
    """Return True if the URL's hostname is exactly a known code host."""
    try:
        parsed = urlparse(url)
    except ValueError:
        return False
    host = (parsed.hostname or "").lower()
    return host in _KNOWN_CODE_HOSTS


def _select_repo_url(project_urls: dict) -> str | None:
    """Select a repository URL pointing to a known code host."""
    # Prefer the explicit Source/Repository keys.
    for key in ("Source", "Repository"):
        value = project_urls.get(key)
        if isinstance(value, str) and _is_known_code_host(value):
            return _sanitize(value)
    # Fall back to scanning every advertised URL.
    for value in project_urls.values():
        if isinstance(value, str) and _is_known_code_host(value):
            return _sanitize(value)
    return None


def _build_provenance_urls(name: str, version: str, data: object) -> list[str]:
    """Build the integrity URL from the first file listed by PyPI."""
    urls = data.get("urls") if isinstance(data, dict) else None
    if not urls:
        return []
    filename = urls[0].get("filename")
    if not filename:
        return []
    return [f"{PYPI_BASE}/integrity/{name}/{version}/{filename}/provenance"]


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata for ``name``/``version`` from PyPI."""
    versioned_url = f"{PYPI_BASE}/pypi/{name}/{version}/json"
    data, status = _get_json(versioned_url)

    if status == 404:
        # Fall back to the latest-release endpoint for repo metadata.
        latest_url = f"{PYPI_BASE}/pypi/{name}/json"
        latest_data, _ = _get_json(latest_url)
        if latest_data is None:
            return PypiPackageInfo(
                project_urls={},
                repo_url=None,
                file_provenance_urls=[],
                found=False,
            )
        project_urls = _extract_project_urls(latest_data)
        return PypiPackageInfo(
            project_urls=project_urls,
            repo_url=_select_repo_url(project_urls),
            file_provenance_urls=[],
            found=False,
        )

    if data is None:
        # Network error, 5xx, or invalid JSON on the versioned endpoint.
        return PypiPackageInfo(
            project_urls={},
            repo_url=None,
            file_provenance_urls=[],
            found=False,
        )

    project_urls = _extract_project_urls(data)
    return PypiPackageInfo(
        project_urls=project_urls,
        repo_url=_select_repo_url(project_urls),
        file_provenance_urls=_build_provenance_urls(name, version, data),
        found=True,
    )


def _parse_bundles(data: object) -> ProvenanceResult | None:
    """Parse attestation bundles, returning None if no usable kind is found."""
    bundles = data.get("attestation_bundles") if isinstance(data, dict) else None
    if not bundles:
        return None
    for bundle in bundles:
        publisher = bundle.get("publisher") or {}
        kind = publisher.get("kind")
        if not kind:
            # Skip entries without a publisher kind.
            continue
        publisher_kind = _sanitize(kind)
        recognized = publisher_kind == "GitHub"
        detail = (
            f"PEP 740 provenance attestation present, published by "
            f"{publisher_kind}."
        )
        if not recognized:
            detail = (
                f"PEP 740 provenance attestation present but publisher "
                f"{publisher_kind} is not a recognized trusted publisher."
            )
        return ProvenanceResult(
            has_attestation=True,
            publisher_kind=publisher_kind,
            recognized_publisher=recognized,
            detail=detail,
        )
    return None


def check_provenance(pkg: PypiPackageInfo) -> ProvenanceResult:
    """Check PEP 740 provenance attestations for a package."""
    if not pkg.found:
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="Package version not found on PyPI; cannot verify provenance.",
        )

    all_404 = True
    for url in pkg.file_provenance_urls:
        data, status = _get_json(url)
        if status == 404:
            continue
        all_404 = False
        if data is None:
            # Non-404 error (5xx / invalid JSON); try the next URL.
            continue
        parsed = _parse_bundles(data)
        if parsed is not None:
            return parsed
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail=(
                "Provenance attestation present but the publisher kind "
                "could not be parsed."
            ),
        )

    if all_404:
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="No PEP 740 provenance attestation present",
        )

    return ProvenanceResult(
        has_attestation=False,
        publisher_kind=None,
        recognized_publisher=False,
        detail="No PEP 740 provenance attestation present",
    )
