from __future__ import annotations

from .diff import parse_diff
from .models import CheckKind, CheckResult, CheckRunResult, CheckStatus
from .pypi import (
    ProvenanceResult,
    PypiPackageInfo,
    check_provenance,
    fetch_package_info,
)


def _build_checks(
    info: PypiPackageInfo, prov: ProvenanceResult
) -> dict[CheckKind, CheckResult]:
    """Derive the four check results from PyPI info and provenance."""
    if not info.found:
        return {
            CheckKind.CI_UPLOAD: CheckResult(
                CheckStatus.FAIL,
                "Package version was not found on PyPI; upload cannot be verified.",
            ),
            CheckKind.RELEASE_PIPELINE: CheckResult(
                CheckStatus.FAIL,
                "Package version was not found on PyPI; release pipeline "
                "cannot be verified.",
            ),
            CheckKind.REPO_PUBLIC: CheckResult(
                CheckStatus.FAIL,
                "Package version was not found on PyPI; repository cannot be "
                "verified.",
            ),
            CheckKind.PR_LINK: CheckResult(
                CheckStatus.FAIL,
                "Package version was not found on PyPI; PR link cannot be "
                "verified.",
            ),
        }

    checks: dict[CheckKind, CheckResult] = {}

    if prov.has_attestation and prov.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.PASS,
            f"Upload is attested by a recognized publisher ({prov.publisher_kind}).",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.PASS,
            f"Release pipeline verified via PEP 740 attestation "
            f"({prov.publisher_kind}).",
        )
    elif prov.has_attestation and not prov.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            f"Upload has an attestation but the publisher is unrecognised "
            f"({prov.publisher_kind}).",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Release pipeline attestation publisher unrecognised "
            f"({prov.publisher_kind}); manual review required.",
        )
    else:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            f"No provenance attestation found for the upload. {prov.detail}",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No PEP 740 attestation present; manual verification of the "
            "release pipeline is required.",
        )

    if info.repo_url:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Package advertises repository {info.repo_url}; verify it is "
            "public and matches the package.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Verify a corresponding pull request or commit exists in "
            f"{info.repo_url}.",
        )
    else:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.FAIL,
            "Package does not advertise a source repository URL.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.FAIL,
            "No repository URL is available to link a pull request.",
        )

    return checks


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse a diff, fetch PyPI info, and run all checks for each change."""
    packages = parse_diff(diff_text)
    for package in packages:
        info = fetch_package_info(package.name, package.new_version)
        prov = check_provenance(info)
        package.repo_url = info.repo_url
        package.checks = _build_checks(info, prov)
    return CheckRunResult(pr_number=pr_number, packages=packages)
